/* BrainU for Principles of Robot Autonomy: an unofficial study companion.
 * Two questions build a path through the course; each lesson links to the real
 * lecture, chapter and notebook, checks you with a question, and points on to
 * current research. Preact + htm, no build step; only what changes re-renders.
 * Course data: prototype/course.json, generated by courses/pora/build.py. */
import { h, render } from "preact";
import { useState, useEffect, useLayoutEffect, useRef, useMemo } from "preact/hooks";
import htm from "./vendor/preact/htm.module.js";

const html = htm.bind(h);
const KEY = "brainu-prototype-v1";
// Progress lives in this browser only (there's no account), so nothing typed is kept.
const SAVED = ["bg", "goal", "started", "i", "done", "passed", "wrong", "tick", "miniOff",
  "placed", "seen", "rev", "last", "days", "weekGoal", "mins", "plan"];
const DAY = 864e5, now = () => Date.now();
// Analytics (GoatCounter, set up in index.html). Pages are hash routes, so count them by
// hand; events are counted as paths starting with "event/". Nothing personal is sent.
function track(path, title, event) {
  const go = () => window.goatcounter && window.goatcounter.count && window.goatcounter.count({ path, title: title || path, event: !!event });
  if (!window.GOATCOUNTER_CODE) return;
  if (window.goatcounter && window.goatcounter.count) go(); else setTimeout(go, 1500);
}
const trackEvent = (name) => track("event/" + name, name, true);
const today = () => new Date().toISOString().slice(0, 10);
const trunc = (t, n) => (t.length > n ? t.slice(0, n - 1) + "…" : t);
// Math: course text writes TeX between $...$; KaTeX (vendored, loaded before this module)
// turns it into typeset math. Plain parts are escaped; `code` becomes <code>.
const escHtml = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
const texCache = new Map();
function tex(s, isHtml) {
  const K = window.katex, key = (isHtml ? "h" : "t") + s;
  if (K && texCache.has(key)) return texCache.get(key);
  const out = String(s ?? "").split(/(\$\$[\s\S]+?\$\$|\$[^$]+\$)/).map((part, k) => {
    if (!(k % 2)) return isHtml ? part : escHtml(part).replace(/`([^`]+)`/g, "<code>$1</code>");
    const disp = part.startsWith("$$"), src = disp ? part.slice(2, -2) : part.slice(1, -1);
    if (!K) return escHtml(src);
    try { return K.renderToString(src, { displayMode: disp, throwOnError: false, output: "html" }); } catch (e) { return escHtml(src); }
  }).join("");
  if (K) texCache.set(key, out); // typesetting is the slow part; each string is typeset once
  return out;
}
const M = ({ t, as = "span", cls }) => h(as, { class: cls, dangerouslySetInnerHTML: { __html: tex(t) } });
const reduceMotion = () => window.matchMedia && matchMedia("(prefers-reduced-motion: reduce)").matches;

// ── course logic ────────────────────────────────────────────────────
function ancestors(C, id) {
  const out = new Set(), st = [...C[id].p];
  while (st.length) { const x = st.pop(); if (!out.has(x)) { out.add(x); st.push(...C[x].p); } }
  return out;
}
// One path covering every goal: what the goals need, minus what you know, in a valid order.
// `placed` is the placement check's verdict: concepts it showed you know, and ones you don't
// (even if your background said you would). Untested concepts fall back to the background.
function pathFor(D, bgId, goals, placed) {
  const C = D.C, bg = D.BG.find((b) => b.id === bgId) || D.BG[0], gs = [].concat(goals || []);
  const K = new Set(bg.k); (placed?.unknown || []).forEach((x) => K.delete(x)); (placed?.known || []).forEach((x) => K.add(x));
  const need = new Set();
  gs.forEach((g) => { need.add(g); ancestors(C, g).forEach((a) => need.add(a)); });
  const keepSet = new Set([...need].filter((x) => gs.includes(x) || !K.has(x)));
  const chk = (x) => (C[x].c == null ? -1 : C[x].c), order = {}, depth = {};
  Object.keys(C).forEach((k, n) => (order[k] = n));
  const dep = (x) => depth[x] ?? (depth[x] = C[x].p.length ? 1 + Math.max(...C[x].p.map(dep)) : 0);
  const out = [], seen = new Set();
  const visit = (x) => { if (seen.has(x)) return; seen.add(x); C[x].p.filter((p) => keepSet.has(p)).sort((a, b) => chk(a) - chk(b)).forEach(visit); out.push(x); };
  [...keepSet].sort((a, b) => chk(a) - chk(b) || dep(a) - dep(b) || order[a] - order[b]).forEach(visit);
  return { steps: out, known: [...need].filter((x) => !keepSet.has(x)) };
}
const chName = (D, c) => (c == null ? "Assumed background" : c === 0 ? "Getting started" : "Chapter " + c + ": " + D.CH[c].title);
const goalName = (D, id) => (D.G.find((x) => x.id === id) || {}).n || (D.C[id] || {}).n || "";
const goalsLabel = (D, gs) => { const n = gs.map((g) => goalName(D, g)); return n.length <= 2 ? n.join(" + ") : n[0] + " + " + (n.length - 1) + " more"; };
const arxivSearch = (name) => "https://arxiv.org/search/?searchtype=all&order=-announced_date_first&query=" + encodeURIComponent(name.replace(/\(.*?\)/g, "").replace(/&/g, " ").trim() + " robot");

// ── routing: the hash is the page, so Back works ────────────────────
const parse = () => { const [, a = "", b, c] = location.hash.split("/"); return { page: a, arg: b, part: c }; };
const nav = (to) => { if (location.hash !== to) location.hash = to; };

// ── the course map ──────────────────────────────────────────────────
// Every concept as a pin on cork, grouped by part. Used on the front page (lights
// up as you answer) and beside each lesson (your progress). Nodes keep their DOM
// across updates, so only a node whose state changed animates.
const XS = [52, 172, 300, 428, 556], PART_SHORT = ["Background", "Planning & control", "Perception", "Localization", "Decisions"];
function layoutFor(D) {
  const L = {}, ids = Object.keys(D.C);
  D.PARTS.forEach((p, pi) => {
    const mine = ids.filter((id) => p.chs.includes(D.C[id].c)), half = Math.ceil(mine.length / 2), gap = Math.min(30, 300 / Math.max(1, half));
    mine.forEach((id, k) => {
      const sub = mine.length > 6 ? (k < half ? -1 : 1) : 0, row = mine.length > 6 ? k % half : k;
      L[id] = [XS[pi] + sub * 26 + Math.sin(k * 2.1) * 5, 92 + row * gap + (sub > 0 ? gap / 2 : 0) + Math.cos(k * 1.3) * 4];
    });
  });
  return L;
}

function Spark({ from, to }) {
  const ref = useRef();
  useEffect(() => { const a = ref.current && ref.current.querySelector("animateMotion"); if (a && a.beginElement) a.beginElement(); }, []);
  if (reduceMotion()) return null;
  return html`<circle ref=${ref} r="5" class="spark" cx="0" cy="0"><animateMotion begin="indefinite" dur="1s" fill="freeze" path=${`M${from[0]},${from[1]} L${to[0]},${to[1]}`} /></circle>`;
}

// Pushpins: a domed plastic head with a collar and a highlight, casting a shadow down-right on
// the cork. The gradients are defined once per board.
const PIN_COL = { red: ["#ff9b92", "#d42a20", "#6e0c08"], gold: ["#fff0a6", "#e2a800", "#6e5000"], green: ["#b4ecad", "#2f8f3a", "#123f17"], cream: ["#ffffff", "#ece2c8", "#9c8862"] };
const PinDefs = () => html`<defs>${Object.entries(PIN_COL).map(([k, [a, b, c]]) => html`<radialGradient key=${k} id=${"pp-" + k} cx="35%" cy="30%" r="75%">
  <stop offset="0" stop-color=${a} /><stop offset=".45" stop-color=${b} /><stop offset="1" stop-color=${c} /></radialGradient>`)}</defs>`;
const Pushpin = ({ x, y, c = "red", s = 1, cls = "", d }) => html`<g class=${"pp " + cls} style=${{ transform: `translate(${x}px, ${y}px) scale(${s})`, "--d": d }}>
  <ellipse cx="3.4" cy="5.6" rx="5.4" ry="2.7" fill="rgba(30,14,2,.36)" />
  <circle r="6.2" fill=${`url(#pp-${c})`} /><circle r="3.3" cx="-.4" cy="-.5" fill=${`url(#pp-${c})`} stroke="rgba(0,0,0,.22)" stroke-width=".5" />
  <ellipse cx="-2.3" cy="-2.7" rx="2" ry="1.25" fill="#fff" opacity=".78" /></g>`;
// Red yarn between two pins: it sags under its own weight, with a twisted-fibre highlight and a
// shadow on the cork. `d` is also set as a style so a moved card drags its yarn smoothly.
// The sag grows with the horizontal span, so a strand hanging straight down stays straight.
const yarnD = (a, b) => { const sag = 3 + Math.abs(b[0] - a[0]) * 0.16;
  return `M${a[0].toFixed(1)},${a[1].toFixed(1)} Q${((a[0] + b[0]) / 2).toFixed(1)},${((a[1] + b[1]) / 2 + sag).toFixed(1)} ${b[0].toFixed(1)},${b[1].toFixed(1)}`; };
const Yarn = ({ a, b, d: delay, done }) => { const d = yarnD(a, b), st = { d: `path("${d}")` };
  return html`<g class=${"yarn" + (done ? " yarn-done" : "")} style=${{ "--d": delay }}>
    <path d=${d} style=${st} class="yn-sh" /><path d=${d} style=${st} class="yn" /><path d=${d} style=${st} class="yn-tw" /><path d=${d} style=${st} class="yn-tw2" /></g>`; };

// The big board: each lesson on your path is an index card pinned in its part's column, in path
// order, with yarn from pin to pin. Everything else stays as a small tack in the background.
const CARD_W = 108, CARD_H = 42;
function boardFor(D, steps) {
  const at = {}, by = D.PARTS.map(() => []);
  steps.forEach((id) => { const pi = D.PARTS.findIndex((p) => p.chs.includes(D.C[id].c)); by[Math.max(0, pi)].push(id); });
  by.forEach((list, pi) => { const gap = Math.min(50, 296 / Math.max(1, list.length));
    list.forEach((id, k) => (at[id] = { x: Math.min(548, Math.max(60, XS[pi] + (k % 2 ? 6 : -6))), y: 98 + CARD_H / 2 + k * gap, rot: [-2.4, 1.8, -1.1, 2.6, -0.7, 1.4][(k + pi * 2) % 6] })); });
  return at;
}
// a lesson name in pen, on at most two short lines, clear of the pin in the card's top-right corner
function cardLines(name) {
  const words = name.replace(/\s*\(.*?\)/, "").split(" "), out = [""];
  for (const w of words) { const cur = out[out.length - 1]; if ((cur + " " + w).trim().length <= 15 || !cur) out[out.length - 1] = (cur + " " + w).trim(); else out.push(w); }
  return (out.length > 2 ? [out[0], out.slice(1).join(" ")] : out).map((t) => trunc(t, 15));
}

function CourseMap({ D, known = [], goals = [], steps = [], current = -1, done = {}, compact = false, pulse = null, onPick }) {
  const L = useMemo(() => layoutFor(D), [D]), ids = Object.keys(D.C), K = new Set(known), at = {};
  steps.forEach((id, k) => (at[id] = k));
  const state = (id) => id in at && at[id] === current ? "now" : goals.includes(id) ? "goal" : id in at ? (done[id] ? "done" : "path") : K.has(id) ? "known" : "dim";
  const f = (v) => v.toFixed(1), grow = compact ? 1.45 : 1;
  const click = (id) => (onPick && at[id] != null ? () => onPick(at[id]) : null);
  const keys = (fn) => (fn ? (e) => (e.key === "Enter" || e.key === " ") && (e.preventDefault(), fn()) : null);
  const label = steps.length ? `Course map: ${steps.length} lessons on your path${current >= 0 ? ", you are on lesson " + (current + 1) : ""}.` : "Course map of 69 concepts";

  if (!compact) {
    const B = boardFor(D, steps), pinAt = (id) => [B[id].x + CARD_W / 2 - 11, B[id].y - CARD_H / 2 + 6];
    const colour = (st) => (st === "goal" ? "gold" : st === "done" ? "green" : "red");
    return html`<svg class="cmap cmap-board" viewBox="0 0 610 420" role="img" aria-label=${label}><${PinDefs} />
      ${D.PARTS.map((p, pi) => html`<g key=${"l" + pi} transform=${`translate(${XS[pi]} 44) rotate(${[-2, 1, -1, 2, -1.5][pi]})`}>
        <rect x="-53" y="-12" width="108" height="26" fill="rgba(40,18,4,.28)" /><rect x="-54" y="-14" width="108" height="26" fill="#fbf9f1" />
        <text y="4" text-anchor="middle" class="gl">${PART_SHORT[pi] || trunc(p.t, 18)}</text>
        <rect x="-13" y="-19" width="26" height="9" fill="rgba(250,246,226,.62)" stroke="rgba(120,100,60,.12)" stroke-width=".6" transform=${`rotate(${[3, -4, 2, -2, 4][pi]})`} /></g>`)}
      ${ids.filter((id) => !(id in at)).map((id) => { const st = state(id);
        return html`<g key=${"k" + id}><title>${D.C[id].n}${st === "known" ? " · you know this" : ""}</title>
          <${Pushpin} x=${L[id][0]} y=${L[id][1]} c=${st === "known" ? "green" : "cream"} s=${st === "known" ? 0.55 : 0.42} cls=${"tack tack-" + st} /></g>`; })}
      ${steps.map((id, k) => { const st = state(id), b = B[id], go = click(id), lines = cardLines(D.C[id].n);
        return html`<g key=${"c" + id} class=${"pc pc-" + st + (go ? " pc-click" : "")} style=${{ transform: `translate(${b.x}px, ${b.y}px) rotate(${b.rot}deg)`, "--d": Math.min(0.9, 0.08 + k * 0.07).toFixed(2) + "s" }}
            onClick=${go} role=${go ? "button" : null} tabindex=${go ? 0 : null} onKeyDown=${keys(go)} aria-label=${"Lesson " + (k + 1) + ": " + D.C[id].n}>
          <title>${"Lesson " + (k + 1) + ": " + D.C[id].n}${st === "goal" ? " · your goal" : st === "done" ? " · done" : ""}</title>
          <g class="pc-in">
          <rect x=${-CARD_W / 2 + 2} y=${-CARD_H / 2 + 3} width=${CARD_W} height=${CARD_H} class="pc-sh" />
          <rect x=${-CARD_W / 2} y=${-CARD_H / 2} width=${CARD_W} height=${CARD_H} class="pc-paper" />
          ${st === "now" ? null : html`<line x1=${-CARD_W / 2} x2=${CARD_W / 2} y1="-9.5" y2="-9.5" class="pc-red" />
            <line x1=${-CARD_W / 2} x2=${CARD_W / 2} y1="2.5" y2="2.5" class="pc-blue" /><line x1=${-CARD_W / 2} x2=${CARD_W / 2} y1="14" y2="14" class="pc-blue" />`}
          <text x=${-CARD_W / 2 + 6} y="-12" class="pc-num">${st === "now" ? "UP NEXT · " : ""}#${k + 1}</text>
          ${st === "goal" ? html`<text x=${CARD_W / 2 - 22} y="-12" text-anchor="end" class="pc-stamp">GOAL</text>` : null}
          ${st === "done" ? html`<path d=${`M${CARD_W / 2 - 34} -15 l3 3 l7 -7`} class="pc-tick" />` : null}
          ${lines.map((t, j) => html`<text key=${j} x=${-CARD_W / 2 + 6} y=${(lines.length > 1 ? 0.5 : 6.5) + j * 11.5} class="pc-name">${t}</text>`)}
          </g></g>`; })}
      ${steps.slice(1).map((id, k) => html`<${Yarn} key=${"y" + steps[k] + id} a=${pinAt(steps[k])} b=${pinAt(id)} d=${(0.25 + k * 0.07).toFixed(2) + "s"} done=${current >= 0 && k < current} />`)}
      ${steps.map((id, k) => { const [x, y] = pinAt(id); return html`<${Pushpin} key=${"p" + id} x=${x} y=${y} c=${colour(state(id))} s=${state(id) === "goal" ? 1.15 : 1} cls="pp-on" d=${Math.min(0.9, 0.2 + k * 0.07).toFixed(2) + "s"} />`; })}
    </svg>`;
  }

  // Beside a lesson the map zooms to your path so the pins are big enough to read and tap.
  let vb = "0 0 610 420";
  if (steps.length) {
    const pts = steps.concat(goals).filter((id) => L[id]).map((id) => L[id]), xs = pts.map((p) => p[0]), ys = pts.map((p) => p[1]);
    let x0 = Math.min(...xs) - 34, x1 = Math.max(...xs) + 34, y0 = Math.min(...ys) - 34, y1 = Math.max(...ys) + 34;
    const w = Math.max(x1 - x0, 260), hgt = Math.max(y1 - y0, w * 0.62), cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
    vb = `${(cx - w / 2).toFixed(0)} ${(cy - hgt / 2).toFixed(0)} ${w.toFixed(0)} ${hgt.toFixed(0)}`;
  }
  const onTop = (id) => id in at || goals.includes(id);
  const pin = (id) => { const st = state(id), [x, y] = L[id], k = at[id], go = click(id);
    const r = (st === "goal" ? 8 : st === "now" ? 8 : st === "path" || st === "done" ? 6.5 : st === "known" ? 5 : 3.6) * grow;
    const tip = D.C[id].n + (st === "known" ? " · you know this" : st === "goal" ? " · your goal" : k != null ? " · lesson " + (k + 1) : "");
    return html`<g key=${id} class=${"gn gn-" + st + (go ? " gn-click" : "")} style=${{ "--d": Math.min(0.6, k != null ? k * 0.05 : (ids.indexOf(id) % 12) * 0.04).toFixed(2) + "s" }}
        onClick=${go} role=${go ? "button" : null} tabindex=${go ? 0 : null} aria-label=${go ? tip : null} onKeyDown=${keys(go)}>
      <title>${tip}</title>
      ${st === "goal" || st === "now" ? html`<circle cx=${f(x)} cy=${f(y)} r=${f(r + 5)} class="gn-ring" />` : null}
      <circle cx=${f(x + r * 0.22)} cy=${f(y + r * 0.38)} r=${f(r * 1.05)} fill="rgba(40,18,4,.32)" />
      <circle cx=${f(x)} cy=${f(y)} r=${f(r)} class="gn-dot" />
      <ellipse cx=${f(x - r * 0.3)} cy=${f(y - r * 0.34)} rx=${f(r * 0.36)} ry=${f(r * 0.26)} class="gn-hi" />
      ${st === "now" ? html`<text x=${f(x)} y=${f(y + 4)} text-anchor="middle" class="gn-num-big">${k + 1}</text>` : null}
    </g>`;
  };
  return html`<svg class="cmap cmap-compact" viewBox=${vb} role="img" aria-label=${label}>
    ${ids.filter((id) => !onTop(id)).map(pin)}
    ${steps.slice(1).map((id, k) => html`<${Yarn} key=${"y" + steps[k] + id} a=${L[steps[k]]} b=${L[id]} d="0s" done=${current >= 0 && k < current} />`)}
    ${ids.filter(onTop).map(pin)}
    ${pulse && L[steps[pulse.from]] && L[steps[pulse.from + 1]] ? html`<${Spark} key=${"p" + pulse.key} from=${L[steps[pulse.from]]} to=${L[steps[pulse.from + 1]]} />` : null}
  </svg>`;
}

const Legend = ({ items }) => html`<div class="glegend">${items.map(([cls, t]) => html`<span key=${cls}><i class=${cls}></i>${t}</span>`)}</div>`;

// ── meeting you where you are ───────────────────────────────────────
// Placement: the graph picks the most informative question next. A right answer means you
// know that concept and everything under it; a wrong one means you'll learn it and
// everything built on it. Up to 8 questions.
function descendantsIn(C, id, pool) {
  const out = new Set(), st = [id];
  while (st.length) { const x = st.pop(); for (const y of pool) if (!out.has(y) && C[y].p.includes(x)) { out.add(y); st.push(y); } }
  return out;
}
function nextPlacement(D, pool, status, bgK) {
  const C = D.C, open = pool.filter((x) => !status[x]);
  let best = null, bestScore = -1;
  for (const x of open) {
    const up = [...ancestors(C, x)].filter((a) => open.includes(a)).length, down = [...descendantsIn(C, x, open)].length;
    const score = Math.min(up + 1, down + 1) * 10 + (bgK.has(x) ? 3 : 0) - ancestors(C, x).size * 0.01;
    if (score > bestScore) { best = x; bestScore = score; }
  }
  return best;
}

// Each lesson has parts you can do in one sitting, with honest minute estimates.
const words = (h) => String(h || "").replace(/<[^>]+>/g, " ").replace(/\$[^$]*\$/g, " x ").split(/\s+/).filter(Boolean).length;
const mmss = (t) => { const p = String(t).split(":").map(Number); return p.length === 3 ? p[0] * 60 + p[1] + p[2] / 60 : p[0] + (p[1] || 0) / 60; };
function partsOf(c) {
  // in the order the lesson page shows them, so the session walks straight down it
  const out = [];
  if ((c.V || []).length) out.push({ part: "watch", label: "Watch: " + c.V[0].t.split(" | ")[0], min: Math.max(2, Math.round(mmss(c.V[0].len))) });
  out.push({ part: "read", label: c.T ? "Read the lesson" : "Read the key ideas", min: c.T ? Math.max(3, Math.round(words(c.T) / 200) + 1) : 2 });
  out.push({ part: "check", label: "Check yourself", min: 2 });
  out.push({ part: "practice", label: "Practice", min: 15, optional: true });
  return out;
}
const isSeen = (S, id, part) => !!(S.seen && S.seen[id] && S.seen[id][part]) || (part === "check" && S.done[id]);
// Plan a session of about `mins` minutes from where you left off: unseen parts, in order.
function sessionPlan(D, S, P, mins) {
  const out = []; let total = 0;
  for (let k = Math.min(S.i, P.steps.length - 1); k < P.steps.length && total < mins; k++) {
    const id = P.steps[k];
    for (const pt of partsOf(D.C[id])) {
      if (isSeen(S, id, pt.part) || (pt.optional && mins < 45)) continue;
      if (total >= mins) break;
      // short on time: the written lesson covers what the video does, so the video waits
      if (pt.part === "watch" && D.C[id].T && pt.min > mins - total) continue;
      out.push({ ...pt, id, k, name: D.C[id].n }); total += pt.min;
    }
  }
  return { parts: out, total };
}

// A session's parts, one group per lesson, for listing them a lesson to a line.
const byLesson = (parts) => parts.reduce((out, x) => { const g = out[out.length - 1]; if (g && g[0].id === x.id) g.push(x); else out.push([x]); return out; }, []);

// Spaced review: a passed lesson comes back after 2 days, then 3, 7, 21 and 60.
const GAPS = [2, 3, 7, 21, 60];
const dueReviews = (S, P) => P.steps.filter((id) => S.done[id] && S.rev && S.rev[id] && S.rev[id].due <= now())
  .sort((a, b) => S.rev[a].due - S.rev[b].due);

// Listening: math is read out in words so a lesson works on a commute.
function sayMath(src) {
  if (/\\begin\{/.test(src)) return " (the matrix is on screen) ";
  let x = src;
  for (const [re, to] of [[/\\ddot\s*\{?\\?([A-Za-z]+)\}?/g, "$1 double dot"], [/\\dot\s*\{?\\?([A-Za-z]+)\}?/g, "$1 dot"],
    [/\\frac\{([^{}]*)\}\{([^{}]*)\}/g, "$1 over $2"], [/\\sqrt\{([^{}]*)\}/g, "the square root of $1"], [/\^\{?2\}?/g, " squared"],
    [/\^\{?\\top\}?/g, " transpose"], [/\^\{?-1\}?/g, " inverse"], [/_\{([^{}]*)\}/g, " sub $1"], [/_([A-Za-z0-9])/g, " sub $1"],
    [/\\operatorname\{([a-z0-9]+)\}/g, "$1"], [/\\(theta|omega|delta|lambda|tau|pi|alpha|beta|gamma|zeta)/g, "$1"], [/\\int/g, "the integral of"],
    [/\\approx/g, " is about "], [/\\neq/g, " is not "], [/\\in/g, " in "], [/\\times/g, " by "], [/\\partial/g, "partial "],
    [/\\Longrightarrow/g, ", so "], [/=/g, " equals "], [/\+/g, " plus "], [/(\s)-(\s)/g, "$1minus$2"], [/</g, " is less than "], [/>/g, " is greater than "],
    [/\\[a-zA-Z]+/g, " "], [/[{}\\|&]/g, " "]]) x = x.replace(re, to);
  return " " + x.replace(/\s+/g, " ").trim() + " ";
}
function speakable(c) {
  const doc = document.createElement("div");
  doc.innerHTML = String(c.T || c.i.map((t) => "<p>" + t + "</p>").join("")).replace(/\$\$([\s\S]+?)\$\$|\$([^$]+)\$/g, (m, a, b) => sayMath(a || b));
  return [c.n + ".", c.s.replace(/\$([^$]+)\$/g, (m, a) => sayMath(a)), ...[...doc.querySelectorAll("h3,p,li,aside")].map((n) => n.textContent.trim()).filter(Boolean)];
}

// Bring your problem: match your words against the course's own concept text.
const STOP = new Set("a an the and or of to in on for with my our is are be it its i we you that this how what want need make get my robot robots".split(" "));
const SYN = { drift: "localization odometry kalman", lost: "localization", where: "localization", map: "slam mapping", camera: "camera vision image",
  see: "camera vision detection", recognize: "detection recognition", obstacle: "planning obstacle collision", avoid: "planning obstacle",
  path: "path planning trajectory", follow: "tracking trajectory", steer: "control tracking", wobble: "pid control damping", oscillate: "pid control damping",
  balance: "lqr control stabilizing", arm: "kinematic", learn: "learning reinforcement imitation", demonstration: "imitation behavior cloning",
  noisy: "noise filter kalman", sensor: "sensor measurement fusion", lidar: "point cloud lidar", gps: "localization fusion", drone: "quadrotor control" };
const stem = (w) => w.replace(/(ing|ed|es|s)$/, "");
function suggestGoals(D, text) {
  let toks = text.toLowerCase().match(/[a-z0-9]+/g) || [];
  toks = toks.filter((t) => !STOP.has(t) && t.length > 2);
  toks = toks.concat(...toks.map((t) => (SYN[t] || SYN[stem(t)] || "").split(" ").filter(Boolean)));
  const T = new Set(toks.map(stem));
  if (!T.size) return [];
  const score = (id) => { const c = D.C[id]; let s = 0;
    for (const w of (c.n.toLowerCase().match(/[a-z0-9]+/g) || [])) if (T.has(stem(w))) s += 3;
    for (const w of (c.s.toLowerCase().match(/[a-z0-9]+/g) || [])) if (T.has(stem(w))) s += 1;
    return s + (D.G.some((g) => g.id === id) ? 1.5 : 0); };
  return Object.keys(D.C).filter((id) => D.C[id].c != null).map((id) => [id, score(id)]).filter(([, v]) => v >= 3).sort((a, b) => b[1] - a[1]).slice(0, 4).map(([id]) => id);
}

// Weekly rhythm, not a streak: count the days you studied this week.
const weekStart = () => { const d = new Date(); d.setHours(0, 0, 0, 0); d.setDate(d.getDate() - ((d.getDay() + 6) % 7)); return d.getTime(); };
const daysThisWeek = (S) => (S.days || []).filter((d) => new Date(d + "T12:00:00").getTime() >= weekStart()).length;

// ── pages ───────────────────────────────────────────────────────────
// Home, your path, and exploring, plus the one thing to do next, always in reach.
function TopNav({ page, hasPath, next }) {
  const link = (to, label, on) => html`<a class="am-nav__link" href=${to} aria-current=${on ? "page" : null}>${label}</a>`;
  return html`<nav class="am-nav top" aria-label="Main">
    <a class="am-nav__brand brand" href="#/home">BrainU<small>unofficial companion to Principles of Robot Autonomy</small></a>
    <div class="am-nav__links">
      ${link("#/home", "Home", page === "home")}
      ${hasPath ? link("#/", "My path", page === "" || page === "path" || page === "lesson" || page === "done") : null}
      ${link("#/explore", "Explore", page === "explore" || page === "graph")}
      ${hasPath && next && page !== "lesson" ? html`<a class="am-button nav-go" href=${next.href}>${next.label} →</a>` : null}
    </div></nav>`;
}

// Minutes to work through a path: the parts a lesson asks of you, practice left out.
const pathMinutes = (D, steps) => steps.reduce((t, id) => t + partsOf(D.C[id]).filter((p) => !p.optional && p.part !== "watch").reduce((a, p) => a + p.min, 0), 0);
const roughTime = (m) => (m < 50 ? "under an hour" : m < 90 ? "about an hour" : "about " + Math.round(m / 60) + " hours");

// The front door: what this is in one line, one button, and something to play with.
// Tap a goal on the cork and watch its path pin itself; left alone, it cycles through them.
function Welcome({ D, set, next, onReset }) {
  const G = D.G, [gi, setGi] = useState(0), [touched, setTouched] = useState(false);
  useEffect(() => { if (touched || reduceMotion()) return; const t = setInterval(() => setGi((k) => (k + 1) % G.length), 3400); return () => clearInterval(t); }, [touched]);
  const g = G[gi], P = pathFor(D, "new", [g.id]);
  const go = () => { trackEvent(touched ? "welcome-goal/" + g.id : "welcome-start"); set(touched ? { goal: [g.id] } : {}); nav("#/start"); };
  return html`<main class="welcome-page">
    <section class="wl-copy">
      <span class="wl-kick">Free · built on Stanford's <i>Principles of Robot Autonomy</i></span>
      <h1>Learn robot autonomy. <span>Only the parts you need.</span></h1>
      <p>Say what you want a robot to do. BrainU strings together the few lessons that get you there, each with the Stanford lecture, a notebook to run, and a two-minute check.</p>
      ${next ? html`<div class="wl-cta"><a class="am-button wl-go" href=${next.href}>${next.label} →</a>
          <span class="wl-sub">your path is saved in this browser</span></div>
        <button class="linkish wl-reset" onClick=${onReset}>Start over with a new path</button>`
      : html`<div class="wl-cta"><button class="am-button wl-go" onClick=${go}>${touched ? "Start with this goal" : "Find my path"} →</button>
        <span class="wl-sub">two questions · about a minute</span></div>`}
      <a class="wl-alt" href="courses/pora-atlas.html">in a hurry? see every concept on one page</a>
    </section>
    <section class="wl-play" aria-label="Try it: pick a goal and see its path">
      <div class="cork cork-sm"><${CourseMap} D=${D} goals=${[g.id]} steps=${P.steps} /></div>
      <p class="wl-say"><b>${g.n}</b>: ${P.steps.length} lessons from scratch, ${roughTime(pathMinutes(D, P.steps))}. Fewer if you know some already.</p>
      <div class="wl-goals" role="group" aria-label="Goals">${G.map((x, k) => html`<button key=${x.id} aria-pressed=${k === gi} class=${k === gi ? "on" : ""}
        onClick=${() => { setTouched(true); setGi(k); }}>${x.n}</button>`)}</div>
    </section>
  </main>`;
}

function Start({ D, S, set }) {
  const [q, setQ] = useState(S.bg ? 2 : 1);
  const [bg, setBg] = useState(S.bg);
  const [goals, setGoals] = useState(S.goal || []);
  const [problem, setProblem] = useState(""), [sugg, setSugg] = useState(null);
  // placement state: verdicts so far, the question on screen, the answer picked
  const [status, setStatus] = useState({}), [asked, setAsked] = useState(0), [pick, setPick] = useState(null);
  const bgObj = D.BG.find((b) => b.id === bg), nIds = Object.keys(D.C).length, C = D.C;
  const placed = { known: Object.keys(status).filter((x) => status[x] === "k"), unknown: Object.keys(status).filter((x) => status[x] === "u") };
  const P = goals.length && bg ? pathFor(D, bg, goals, q === 3 ? placed : null) : { steps: [], known: [] };
  const P0 = goals.length && bg ? pathFor(D, bg, goals) : { steps: [] };
  const pool = useMemo(() => { if (!goals.length) return []; const need = new Set(); goals.forEach((g) => ancestors(C, g).forEach((a) => need.add(a))); return [...need].filter((x) => !goals.includes(x)); }, [goals.join()]);
  const bgK = new Set(bgObj ? bgObj.k : []);
  const cur = q === 3 && asked < 8 ? nextPlacement(D, pool, status, bgK) : null;
  const answer = (right) => {
    const st = { ...status };
    if (right) { st[cur] = "k"; ancestors(C, cur).forEach((x) => { if (pool.includes(x)) st[x] = st[x] || "k"; }); }
    else { st[cur] = "u"; descendantsIn(C, cur, pool).forEach((x) => (st[x] = st[x] || "u")); }
    setStatus(st); setAsked(asked + 1); setPick(null);
  };
  const isOn = (id) => (q === 2 ? goals.includes(id) : bg === id), list = q === 2 ? D.G : D.BG;
  const toggle = (id) => setGoals(goals.includes(id) ? goals.filter((g) => g !== id) : goals.concat(id));
  // one tap answers question 1 and turns the page; Back is there if it was a slip
  const choose = (id) => { if (q === 2) return toggle(id); setBg(id); setTimeout(() => setQ(2), reduceMotion() ? 0 : 280); };
  const finish = (withPlacement) => {
    trackEvent(withPlacement ? "path-built-after-check" : "path-built-skipped-check");
    goals.forEach((g) => trackEvent("goal/" + g)); trackEvent("from/" + bg);
    set({ bg, goal: goals, i: 0, started: false, done: {}, passed: 0, wrong: {}, seen: {}, rev: {}, plan: null,
      placed: withPlacement ? placed : null, justBuilt: Date.now() });
    nav("#/");
  };
  const startCheck = () => { setStatus({}); setAsked(0); setPick(null); setQ(3); };
  const tested = Object.keys(status).length, done3 = q === 3 && !cur;
  const knownNow = q === 3 ? [...new Set([...(bgObj ? bgObj.k : []).filter((x) => status[x] !== "u"), ...placed.known])] : bgObj ? bgObj.k : [];
  const caption = q === 3 ? html`<b>${P.steps.length} lessons</b> for you${P0.steps.length !== P.steps.length ? html` (was ${P0.steps.length})` : ""}. Green is what you've shown you know.`
    : q === 2 && goals.length ? html`<b>${P.steps.length} lessons</b> pinned for you, strung in order. A 2-minute check can make it shorter.`
    : bgObj ? html`You probably know <b>${bgObj.k.length}</b> of ${nIds} concepts. ${q === 1 ? "Next: what do you want to do?" : "Now pick what you want to do."}`
    : html`<b>${nIds} concepts</b> in five parts. Answer and watch your part of the course light up.`;
  const cq = cur && C[cur].q;
  return html`<main class="start">
    <div class="start-grid">
      <section class="qcard" aria-labelledby="qh">
        <div class="qsteps"><button class=${q === 1 ? "on" : ""} onClick=${() => setQ(1)}>① starting point</button><button class=${q === 2 ? "on" : ""} disabled=${!bg} onClick=${() => setQ(2)}>② goal</button><button class=${q === 3 ? "on" : ""} disabled=${!goals.length} onClick=${startCheck}>③ quick check</button></div>
        ${q < 3 ? html`
        <h2 id="qh">${q === 2 ? "What do you want to be able to do?" : "Where are you starting from?"}</h2>
        <p class="qhint">${q === 2 ? "tick as many as you like" : "pick one; the quick check will fine-tune it"}</p>
        <div class="picks" role=${q === 2 ? "group" : "radiogroup"} aria-labelledby="qh">
          ${list.map((o) => html`<button key=${o.id} class=${"pick" + (isOn(o.id) ? " pick-on" : "")} role=${q === 2 ? "checkbox" : "radio"} aria-checked=${isOn(o.id)} onClick=${() => choose(o.id)}>
            <span class=${"circ" + (q === 2 ? " sq" : "")} aria-hidden="true">${isOn(o.id) ? "✓" : ""}</span><span><b>${o.n}</b><span class="d">${o.b}</span></span></button>`)}
        </div>
        ${q === 2 ? html`<div class="problem">
          <label for="prob" class="qhint">or say what you're building, in your words</label>
          <div class="prob-row"><input id="prob" value=${problem} placeholder="e.g. my warehouse robot drifts when it turns" onInput=${(e) => setProblem(e.currentTarget.value)}
            onKeyDown=${(e) => e.key === "Enter" && setSugg(suggestGoals(D, problem))} /><button class="linkish" onClick=${() => setSugg(suggestGoals(D, problem))}>Suggest</button></div>
          ${sugg ? sugg.length ? html`<div class="sugg"><span class="qhint">these parts of the course fit; tick what's right:</span>
              ${sugg.map((id) => html`<button key=${id} class=${"schip" + (goals.includes(id) ? " on" : "")} aria-pressed=${goals.includes(id)} onClick=${() => toggle(id)}>${goals.includes(id) ? "✓ " : "+ "}${C[id].n}</button>`)}</div>`
            : html`<p class="qhint">Nothing in the course matched those words. Try naming the problem: drift, obstacles, camera, balance…</p>` : null}
        </div>` : null}
        <div class="qfoot">
          ${q === 2 ? html`<button class="linkish" onClick=${() => setQ(1)}>‹ Back</button>` : html`<span></span>`}
          ${q === 1 ? html`<button class="am-button" disabled=${!bg} onClick=${() => setQ(2)}>Next question →</button>`
            : html`<span class="qf-r">${goals.length ? html`<button class="linkish" onClick=${() => finish(false)}>Skip, show my ${P.steps.length} lessons</button>` : null}
              <button class="am-button" disabled=${!goals.length} onClick=${startCheck}>${goals.length ? "Quick check, 2 min →" : "Pick at least one"}</button></span>`}
        </div>` : done3 ? html`
        <h2 id="qh">Here's where you are</h2>
        <p class="qhint">${tested} concepts checked from ${asked} questions</p>
        <div class="placed">
          <p><b>${placed.known.length}</b> you already know${placed.known.length ? html`: <span class="dim">${placed.known.map((x) => C[x].n).slice(0, 6).join(", ")}${placed.known.length > 6 ? "…" : ""}</span>` : ""}</p>
          <p><b>${placed.unknown.length}</b> to learn${placed.unknown.length ? html`: <span class="dim">${placed.unknown.map((x) => C[x].n).slice(0, 6).join(", ")}${placed.unknown.length > 6 ? "…" : ""}</span>` : ""}</p>
          <p class="big">Your path: <b>${P.steps.length} lessons</b>${P0.steps.length !== P.steps.length ? html`, down from ${P0.steps.length}` : P.steps.length ? ", as planned" : ""}. You start with <b>${P.steps.length ? C[P.steps[0]].n : "-"}</b>.</p>
        </div>
        <div class="qfoot"><button class="linkish" onClick=${startCheck}>Redo the check</button><button class="am-button" onClick=${() => finish(true)}>Show my ${P.steps.length} lessons →</button></div>`
        : html`
        <h2 id="qh">Quick check</h2>
        <p class="qhint">question ${asked + 1} of up to 8 · about <b>${C[cur].n}</b> · it's fine not to know</p>
        <${M} as="p" cls="pq" t=${cq[0]} />
        <div class="pq-opts" role="radiogroup" aria-label="Answers">${cq[1].map((t, k) => html`<button key=${k} role="radio" aria-checked=${pick === k} class=${"pick pq-opt" + (pick === k ? " pick-on" : "")} onClick=${() => setPick(k)}>
          <span class="circ" aria-hidden="true">${pick === k ? "✓" : "ABCD"[k]}</span><${M} t=${t} /></button>`)}</div>
        <div class="qfoot"><button class="linkish" onClick=${() => answer(false)}>I don't know this yet</button>
          <span class="qf-r"><button class="linkish" onClick=${() => setAsked(8)}>Stop here</button><button class="am-button" disabled=${pick === null} onClick=${() => answer(pick === cq[2])}>Next →</button></span></div>`}
      </section>
      <aside class="mapwrap" aria-label="The course map, lighting up as you answer">
        <div class="cork cork-sm"><${CourseMap} D=${D} known=${knownNow} goals=${q >= 2 ? goals : []} steps=${q >= 2 ? P.steps : []} /></div>
        <${Legend} items=${[["gl-k", "you know it"], ["gl-p", "your lessons"], ["gl-g", "your goal"]]} />
        <p class="gcap">${caption}</p>
      </aside>
    </div>
  </main>`;
}

// Spaced review: a few questions from lessons you've passed, one at a time.
function Review({ D, S, set, ids: given, onDone, title }) {
  // freeze the questions when the review starts; answering re-sorts what's due
  const [ids] = useState(given), [k, setK] = useState(0), [pick, setPick] = useState(null), [checked, setChecked] = useState(false), [score, setScore] = useState(0);
  if (k >= ids.length) return html`<div class="review-done"><b>${score} of ${ids.length}</b> right. ${score === ids.length ? "It stuck." : "Misses are on your retry list."}
    <button class="am-button" onClick=${onDone}>Carry on →</button></div>`;
  const id = ids[k], c = D.C[id], [q, ch, correct, why] = c.q, ok = pick === correct;
  const check = () => {
    setChecked(true); if (ok) setScore(score + 1);
    const r = (S.rev || {})[id] || { n: 0 }, rev = { ...S.rev };
    if (ok) rev[id] = { n: r.n + 1, due: now() + GAPS[Math.min(r.n + 1, GAPS.length - 1)] * DAY };
    else rev[id] = { n: 0, due: now() + DAY };
    set(ok ? { rev } : { rev, wrong: { ...S.wrong, [id]: { at: S.tick } } });
  };
  return html`<div class="review">
    <span class="kicker">${title} · ${k + 1} of ${ids.length} · from “${c.n}”</span>
    <${M} as="p" cls="qq" t=${q} />
    <div class="qopts">${ch.map((t, j) => html`<button key=${j} disabled=${checked} class=${"qopt" + (checked ? (j === correct ? " qopt-right" : j === pick ? " qopt-wrong" : "") : pick === j ? " qopt-on" : "")} onClick=${() => setPick(j)}>
      <span class="qm">${"ABCD"[j]}</span><${M} t=${t} /></button>`)}</div>
    ${checked ? html`<div class=${"feedback " + (ok ? "fb-ok" : "fb-no")}><b>${ok ? "Right." : "Not quite."}</b> <${M} t=${why} /></div>` : null}
    <div class="row">${checked ? html`<button class="am-button" onClick=${() => { setK(k + 1); setPick(null); setChecked(false); }}>${k + 1 < ids.length ? "Next question →" : "Done"}</button>`
      : html`<button class="am-button" disabled=${pick === null} onClick=${check}>Check</button><button class="linkish" onClick=${onDone}>Skip the review</button>`}</div>
  </div>`;
}

function Home({ D, S, P, set, onReset }) {
  const i = Math.min(S.i, P.steps.length - 1), c = D.C[P.steps[i]], learned = P.steps.filter((id) => S.done[id]).length;
  const away = S.prevLast ? Math.floor((now() - S.prevLast) / DAY) : 0;
  const due = dueReviews(S, P);
  const [warm, setWarm] = useState(away >= 3 && P.steps.some((id) => S.done[id]) ? "offer" : null), [rev, setRev] = useState(false);
  const mins = S.mins || 20, plan = sessionPlan(D, S, P, mins);
  const first = plan.parts[0], wk = daysThisWeek(S), goal = S.weekGoal || 3;
  const startPlan = () => { trackEvent("session-" + mins + "min"); set({ plan: { mins, at: now(), parts: plan.parts.map((x) => x.id + ":" + x.part) } }); nav("#/lesson/" + (first.k + 1) + "/" + first.part); };
  // the warm-up: what you were doing, then three questions from passed lessons (oldest first)
  const warmIds = [...due, ...P.steps.filter((id) => S.done[id] && !due.includes(id)).reverse()].slice(0, 3);
  const lastDone = [...P.steps].reverse().find((id) => S.done[id]);
  const fresh = !S.started && S.justBuilt, left = P.steps.filter((id) => !S.done[id]);
  const retry = Object.keys(S.wrong || {}).filter((w) => P.steps.includes(w));
  return html`<main class=${"home2" + (fresh ? " home-fresh" : "")}>
    ${warm === "offer" ? html`<section class="card welcome">
      <span class="kicker">Welcome back · it's been ${away} days</span>
      <h2>Here's where you were</h2>
      <p>You last passed <b>${lastDone ? D.C[lastDone].n : "your first lesson"}</b>${lastDone ? html`: <${M} t=${D.C[lastDone].i[0]} />` : ""}</p>
      <p>Next up is <b>${c.n}</b>. A 90-second warm-up brings the last lessons back before you go on.</p>
      <div class="row"><button class="am-button" onClick=${() => setWarm("on")}>Warm up, 3 questions</button><button class="linkish" onClick=${() => setWarm(null)}>Skip it</button></div>
    </section>` : warm === "on" ? html`<section class="card welcome"><${Review} D=${D} S=${S} set=${set} ids=${warmIds} title="Warm-up" onDone=${() => setWarm(null)} /></section>` : null}

    <div class="home-main">
    <section class="card homecard">
      ${fresh ? html`<p class="ready"><b>Your path is ready.</b> ${P.steps.length} lessons, ${roughTime(pathMinutes(D, P.steps))}${P.known.length ? html`, skipping ${P.known.length} concept${P.known.length > 1 ? "s" : ""} you already know` : ""}.</p>` : null}
      ${plan.parts.length ? html`
      <span class="kicker">${S.started ? "Pick up where you left off" : "Up first"} · lesson ${i + 1} of ${P.steps.length}</span>
      <h1>${c.n}</h1>
      <${M} as="p" cls="hc-sum" t=${c.s} />
      <div class="hc-time"><span>I have</span><div class="seg3 mins" role="radiogroup" aria-label="Time for this session">${[10, 20, 45].map((m) => html`<button key=${m} role="radio" aria-checked=${mins === m} class=${mins === m ? "on" : ""} onClick=${() => set({ mins: m })}>${m} min</button>`)}</div></div>
      <ol class="plan">${byLesson(plan.parts).map((g) => html`<li key=${g[0].id}><a href=${"#/lesson/" + (g[0].k + 1) + "/" + g[0].part}>
          <span class="pl-k" aria-hidden="true">${g[0].k + 1}</span><span class="pl-t">${g[0].name}</span>
          <span class="pl-n">${g.map((x) => ({ watch: "watch", read: "read", check: "check", practice: "practice" }[x.part])).join(" · ")}</span><span class="pl-m">${g.reduce((t, x) => t + x.min, 0)} min</span></a></li>`)}</ol>
      <div class="row"><button class="am-button hc-go" onClick=${startPlan}>Start my ${mins} minutes →</button>
        <span class="hint">stop after any step; it picks up where you left off</span></div>`
        : html`<span class="kicker">All ${P.steps.length} lessons done</span><h1>You finished the path</h1>
          <div class="row"><a class="am-button hc-go" href="#/done">See where to go next →</a></div>`}
    </section>

    <section class="card trail" aria-labelledby="trh">
      <div class="side-head"><h2 id="trh">Your path · ${goalsLabel(D, S.goal)}</h2><span>${learned} of ${P.steps.length} done${left.length && learned ? " · " + roughTime(pathMinutes(D, left)) + " left" : ""}</span></div>
      <ol class="trail-list">${P.steps.map((id, k) => html`<li key=${id} style=${{ "--k": k }}><a href=${"#/lesson/" + (k + 1)} title=${D.C[id].c == null ? "background" : "chapter " + D.C[id].c}
        class=${"stop" + (S.done[id] ? " stop-done" : "") + (k === i ? " stop-now" : "")}><span class="sn">${S.done[id] ? "✓" : k + 1}</span>${D.C[id].n}</a></li>`)}</ol>
      <div class="row tiny"><a class="linkish" href="#/path">See it on the course map</a><a class="linkish" href="#/start">Change goals</a><button class="linkish" onClick=${onReset}>Start over</button></div>
    </section>
    </div>

    <aside class="home-side">
      ${retry.length ? html`<section class="card retry" aria-labelledby="rt"><h2 id="rt">Retry later</h2>
        <div class="stickies">${retry.map((w, k) => { const ago = S.tick - S.wrong[w].at, due2 = ago >= 2;
          return html`<a key=${w} href=${"#/lesson/" + (P.steps.indexOf(w) + 1) + "/check"} class=${"sticky" + (due2 ? " sticky-due" : "")} style=${{ rotate: [-3, 2, -1.5, 3][k % 4] + "deg" }}>
            <span>${due2 ? "retry now" : "in " + (2 - ago) + " lesson" + (2 - ago > 1 ? "s" : "")}</span>${trunc(D.C[w].n, 40)}</a>`; })}</div></section>` : null}
      ${due.length && warm !== "on" ? html`<section class="card">
        <h2>${due.length} quick review${due.length > 1 ? "s" : ""} due</h2>
        ${rev ? html`<${Review} D=${D} S=${S} set=${set} ids=${due.slice(0, 5)} title="Review" onDone=${() => setRev(false)} />`
          : html`<p class="hint">Lessons you passed come back after 2, 3, 7, 21 and 60 days, so they stick. About ${Math.min(5, due.length)} min.</p>
            <button class="am-button am--secondary" onClick=${() => setRev(true)}>Review now</button>`}
      </section>` : null}
      <section class="card">
        <h2>This week</h2>
        <div class="week" aria-label=${wk + " of " + goal + " study days this week"}>${Array.from({ length: Math.max(goal, wk) }, (_, k) => html`<span key=${k} class=${k < wk ? "on" : ""}></span>`)}</div>
        <p class="hint">${wk >= goal ? "Goal met. Anything more is a bonus." : wk + " of " + goal + " study days. Any day you learn something counts; there's no streak to break."}</p>
        <div class="row tiny">Weekly goal: ${[2, 3, 5].map((g) => html`<button key=${g} class=${"linkish" + (goal === g ? " strong" : "")} aria-pressed=${goal === g} onClick=${() => set({ weekGoal: g })}>${g} days</button>`)}</div>
      </section>
    </aside>
  </main>`;
}

// The path as a corkboard of index cards with red string through your lessons.
function PathPage({ D, S, P, set }) {
  const C = D.C, pos = {}, known = new Set(P.known), i = Math.min(S.i, P.steps.length - 1);
  P.steps.forEach((id, k) => (pos[id] = k));
  const [open, setOpen] = useState({}), [note, setNote] = useState(null);
  const pinning = S.justBuilt && Date.now() - S.justBuilt < 4000 && !reduceMotion();
  const inner = useRef(), [str, setStr] = useState({ d: "", pins: [], w: 0, h: 0 });
  useLayoutEffect(() => {
    const draw = () => {
      const el = inner.current; if (!el) return;
      const o = el.getBoundingClientRect();
      const pts = [...el.querySelectorAll(".chip[data-n]")].sort((a, b) => a.dataset.n - b.dataset.n)
        .map((n) => { const r = n.getBoundingClientRect(); return [r.left - o.left + 12, r.top - o.top + r.height / 2]; });
      let d = "";
      pts.forEach(([x, y], k) => { if (!k) { d = `M${x},${y}`; return; } const [px, py] = pts[k - 1], dist = Math.hypot(x - px, y - py);
        d += ` Q${(px + x) / 2},${Math.max(py, y) + 6 + dist * 0.14} ${x},${y}`; });
      setStr({ d, pins: pts, w: el.scrollWidth, h: el.scrollHeight });
    };
    draw(); const on = () => requestAnimationFrame(draw);
    addEventListener("resize", on); document.fonts && document.fonts.ready.then(on);
    return () => removeEventListener("resize", on);
  }, [P.steps.join(), JSON.stringify(open)]);
  const cols = D.PARTS.map((p, ci) => {
    const ids = Object.keys(C).filter((id) => p.chs.includes(C[id].c)), onPath = ids.some((id) => id in pos), shown = onPath || open[ci];
    return html`<div key=${ci} class=${"col" + (shown ? "" : " col-closed")}>
      <div class="colsub">${ci === 0 ? "MATH THE BOOK ASSUMES" : "PART " + ["I", "II", "III", "IV"][ci - 1]}</div><div class="coltitle">${p.t}</div>
      ${shown ? p.chs.map((n) => { const items = ids.filter((id) => C[id].c === n); if (!items.length) return null;
        return html`<div key=${"ch" + n} class="chgroup">${n != null ? html`<div class="chl">${n === 0 ? "GETTING STARTED" : trunc("CH " + n + " · " + D.CH[n].title.toUpperCase(), 32)}</div>` : null}
          ${items.map((id) => html`<button key=${id} data-n=${id in pos ? pos[id] : null} style=${id in pos ? { "--n": pos[id] } : null} title=${C[id].n}
            class=${"chip " + (S.goal.includes(id) ? "chip-goal" : id in pos ? "chip-path" + (S.done[id] ? " chip-done" : "") : known.has(id) ? "chip-known" : "chip-dim")}
            onClick=${() => setNote(id)}><span class="num">${id in pos ? pos[id] + 1 : ""}</span><span class="nm">${trunc(C[id].n, 26)}</span></button>`)}</div>`; })
      : html`<button class="showcol" onClick=${() => setOpen({ ...open, [ci]: true })}>${ids.length} concepts, not on this path. Show</button>`}
    </div>`;
  });
  const nc = note && C[note];
  return html`<main class="pathpage">
    <section class="card pathlist" aria-labelledby="ph">
      <span class="kicker">Your path · from ${(D.BG.find((b) => b.id === S.bg) || {}).n}</span>
      <h1 id="ph">${goalsLabel(D, S.goal)}</h1>
      <ol>${P.steps.map((id, k) => html`<li key=${id}><a href=${"#/lesson/" + (k + 1)} class=${"step" + (S.done[id] ? " step-done" : "") + (k === i && S.started ? " step-now" : "")}>
        <span class="sn">${S.done[id] ? "✓" : k + 1}</span><span><span class="sname">${C[id].n}</span><span class="smeta">${C[id].c == null ? "background" : "chapter " + C[id].c}${C[id].L.length ? " · lecture" : ""}${C[id].N.length ? " · notebook" : ""}</span></span></a></li>`)}</ol>
      <div class="row"><a class="am-button" href=${"#/lesson/" + (i + 1)}>${S.started ? "Continue lesson " + (i + 1) : "Start lesson 1"} →</a><a class="linkish" href="#/start">Change goals</a></div>
    </section>
    <section class=${"cork cork-board" + (pinning ? " pinning" : "")} aria-labelledby="mh">
      <div class="cork-head"><h2 id="mh" class="paper-label">Where your path goes</h2>
        <${Legend} items=${[["lg-path", "your lessons, pinned in order"], ["lg-goal", "goal"], ["lg-known", "you know it"]]} /></div>
      ${nc ? html`<div class="notecard"><div><b>${nc.n}</b><span>${chName(D, nc.c)} · ${note in pos ? "lesson " + (pos[note] + 1) + " on your path" : known.has(note) ? "you already know this" : pathFor(D, S.bg, [note], S.placed).steps.length + " lessons from where you are"}</span></div>
        <div class="row">${note in pos ? html`<a class="am-button" href=${"#/lesson/" + (pos[note] + 1)}>Open lesson</a>` : !S.goal.includes(note) ? html`<button class="am-button am--secondary" onClick=${() => { setNote(null); set({ goal: S.goal.concat(note), i: 0, started: false }); }}>Add as a goal</button>` : null}
          <button class="linkish" onClick=${() => setNote(null)}>Close</button></div></div>` : null}
      <div class="cork-scroll"><div class="cork-in" ref=${inner}>${cols}
        <svg class="string" width=${str.w} height=${str.h} aria-hidden="true"><${PinDefs} />
          <g class="yarn"><path d=${str.d} class="yn-sh" pathLength="1" /><path d=${str.d} class="yn" pathLength="1" /><path d=${str.d} class="yn-tw" /><path d=${str.d} class="yn-tw2" /></g>
          ${str.pins.map(([x, y], k) => html`<g key=${k} class="pin"><${Pushpin} x=${x} y=${y} c=${k === str.pins.length - 1 ? "gold" : "red"} s=${0.85} /></g>`)}
        </svg></div></div>
      <p class="paper-tip">Follow the red yarn. Tap a card to see where it sits.</p>
    </section>
  </main>`;
}

// Today's session, shown under the lesson bar: each step ticks off as you do it.
function planStrip(D, S, P) {
  if (!S.plan || !S.plan.parts || !S.plan.parts.length) return null;
  const items = S.plan.parts.map((key) => { const [id, part] = key.split(":"); return { id, part, k: P.steps.indexOf(id), ok: isSeen(S, id, part) }; }).filter((x) => x.k >= 0);
  if (!items.length) return null;
  const left = items.filter((x) => !x.ok), name = { watch: "Watch", read: "Read", check: "Check", practice: "Practice" };
  // one line: how far through today's session, and the single next thing to do
  return html`<div class=${"planstrip" + (left.length ? "" : " planstrip-done")} role="status">
    <span class="ps-k">Today · ${S.plan.mins} min</span>
    <span class="ps-dots" aria-label=${items.length - left.length + " of " + items.length + " steps done"}>${items.map((x) => html`<i key=${x.id + x.part} class=${x.ok ? "ok" : ""} title=${name[x.part] + ": " + D.C[x.id].n}></i>`)}</span>
    ${left.length ? html`<a class="ps-next" href=${"#/lesson/" + (left[0].k + 1) + "/" + left[0].part}>Next: ${name[left[0].part].toLowerCase()} ${trunc(D.C[left[0].id].n, 28)} →</a>`
      : html`<span class="ps-next">Session done. <a href="#/">Plan another</a> or stop here; it'll pick up where you left off.</span>`}
  </div>`;
}

// Read the lesson aloud with the browser's own voice. Math is spoken in words.
function Listen({ c, onEnd }) {
  const ok = typeof window !== "undefined" && "speechSynthesis" in window;
  const [st, setSt] = useState("idle"), [rate, setRate] = useState(1);
  useEffect(() => () => ok && speechSynthesis.cancel(), [c.n]);
  if (!ok) return null;
  const lines = speakable(c), mins = Math.max(1, Math.round(lines.join(" ").split(/\s+/).length / 150));
  const play = () => {
    speechSynthesis.cancel();
    lines.forEach((t, k) => { const u = new SpeechSynthesisUtterance(t); u.rate = rate; u.lang = "en-US";
      if (k === lines.length - 1) u.onend = () => { setSt("idle"); onEnd && onEnd(); };
      speechSynthesis.speak(u); });
    setSt("on");
  };
  return html`<div class="listen" role="group" aria-label="Listen to this lesson">
    ${st === "idle" ? html`<button class="am-button am--secondary" onClick=${play}>▶ Listen · ${mins} min</button>`
      : html`<button class="am-button am--secondary" onClick=${() => { if (st === "on") { speechSynthesis.pause(); setSt("paused"); } else { speechSynthesis.resume(); setSt("on"); } }}>${st === "on" ? "❚❚ Pause" : "▶ Resume"}</button>
        <button class="linkish" onClick=${() => { speechSynthesis.cancel(); setSt("idle"); }}>Stop</button>`}
    <label class="hint">speed <select value=${rate} onChange=${(e) => setRate(+e.currentTarget.value)}>${[0.9, 1, 1.25, 1.5].map((r) => html`<option key=${r} value=${r}>${r}×</option>`)}</select></label>
  </div>`;
}

// A lesson is a short deck, one card on screen at a time: the chalkboard intro, one card per
// section of the written lesson, a recap, the video, the check, and practice. Each section is
// one idea, so a card reads in about a minute and nothing needs a long scroll.
function lessonCards(c, hasVideo) {
  // the course's own video comes right after the intro, before the written cards
  const out = [{ k: "intro", t: "Intro" }];
  if (hasVideo) out.push({ k: "watch", t: "Watch" });
  if (c.T) {
    String(c.T).split(/(?=<h3)/).filter((s) => s.trim()).forEach((h) => out.push({ k: "read", h, t: (h.match(/<h3>(.*?)<\/h3>/) || [, "Read"])[1].replace(/<[^>]+>|\$[^$]*\$/g, "").trim() }));
    out.push({ k: "recap", t: "Recap" });
  }
  out.push({ k: "check", t: "Check yourself" }, { k: "practice", t: "Practice" });
  return out;
}

function Lesson({ D, S, P, set, n, part }) {
  const C = D.C, steps = P.steps, total = steps.length, i = Math.max(0, Math.min(n, total - 1)), id = steps[i], c = C[id];
  const prev = i > 0 ? C[steps[i - 1]] : null, next = i < total - 1 ? C[steps[i + 1]] : null;
  const [sel, setSel] = useState(0), [video, setVideo] = useState(null), [picked, setPicked] = useState(null), [checked, setChecked] = useState(false), [playing, setPlaying] = useState(false), [pulse, setPulse] = useState(null);
  const ytOf = (u) => (String(u).match(/(?:youtu\.be\/|v=|embed\/)([\w-]{11})/) || [])[1];
  // short explainers first; the full Stanford class recording stays one tap away
  const vids = [...(c.V || []).map((v) => ({ yt: v.id, title: v.t, by: v.ch, len: v.len })),
    ...c.L.map((l) => ({ yt: ytOf(l.url), title: l.title, by: "Stanford " + l.course + " · lecture " + l.n, len: "full class", url: l.url, full: true }))];
  const cards = useMemo(() => lessonCards(c, vids.length > 0), [id]);
  // #/lesson/3/check opens on that card; plain #/lesson/3 (or /read) opens on the intro
  const cardFor = (pt) => Math.max(0, cards.findIndex((x) => x.k === pt && pt !== "read"));
  const [card, setCard] = useState(() => cardFor(part));
  useEffect(() => { setSel(0); setPicked(null); setChecked(false); setPlaying(false); if (S.i !== i || !S.started) set({ i, started: true }); }, [id]);
  useEffect(() => { setCard(cardFor(part)); }, [id, part]);
  useEffect(() => { window.scrollTo(0, 0); }, [id, card]);
  const seen = (pt) => { if (!isSeen(S, id, pt)) set({ seen: { ...S.seen, [id]: { ...((S.seen || {})[id] || {}), [pt]: 1 } } }); };
  // reading counts once you reach the recap (or move past the intro, when the intro is the lesson)
  useEffect(() => { const k = cards[card] && cards[card].k; if (k === "recap" || (!c.T && card > 0)) seen("read"); }, [card, id]);
  const last = card >= cards.length - 1, nextHref = next ? "#/lesson/" + (i + 2) : "#/done";
  const fwd = () => (last ? nav(nextHref) : setCard(card + 1)), back = () => card > 0 && setCard(card - 1);
  useEffect(() => {
    const k = (e) => { if (e.altKey || e.metaKey || e.ctrlKey || /INPUT|TEXTAREA|SELECT/.test(e.target.tagName)) return;
      if (e.key === "ArrowRight") fwd(); else if (e.key === "ArrowLeft") back(); };
    addEventListener("keydown", k); return () => removeEventListener("keydown", k);
  });
  const [qq, choices, correct, why] = c.q, ok = picked === correct;
  const check = () => {
    setChecked(true);
    const wrong = { ...S.wrong }; if (ok) delete wrong[id]; else wrong[id] = { at: S.tick + 1 };
    const rev = { ...S.rev }; if (ok && !rev[id]) rev[id] = { n: 0, due: now() + GAPS[0] * DAY };
    set({ done: ok ? { ...S.done, [id]: true } : S.done, passed: S.passed + (ok ? 1 : 0), wrong, tick: S.tick + 1, rev,
      seen: { ...S.seen, [id]: { ...((S.seen || {})[id] || {}), check: 1 } } });
    if (ok && next) setPulse({ from: i, key: Date.now() });
    trackEvent(ok ? "check-right" : "check-wrong");
  };
  const nbk = c.N[0], ch = c.c == null ? null : D.CH[c.c];
  const vi = Math.min(sel, Math.max(0, vids.length - 1)), V = vids[vi], yt = V && V.yt;
  const kicker = c.c == null ? "Background the book assumes" : c.c === 0 ? "Getting started" : "Chapter " + c.c + " · " + ch.title;
  const go = (k) => nav("#/lesson/" + (k + 1));
  const ci = Math.min(card, cards.length - 1), cur = cards[ci], nreads = cards.filter((x) => x.k === "read").length;
  const readNo = cards.slice(0, ci + 1).filter((x) => x.k === "read").length;
  const chapterLink = html`<a href=${ch ? ch.url : "https://porabook.com/book/"} target="_blank" rel="noopener">${c.c == null ? "the book" : "chapter " + c.c + " on porabook.com"} ↗</a>`;
  // jump to the video card with a given video picked (the Stanford lecture, from the intro)
  const lecK = vids.findIndex((v) => v.full), watchVid = (k) => { setSel(k); setPlaying(false); setCard(cards.findIndex((x) => x.k === "watch")); };
  const ideas = html`<ol class="ideas">${c.i.map((t, k) => html`<li key=${k}><${M} t=${t} /></li>`)}</ol>`;
  return html`<main class="lesson">
    <div class="lessonbar">
      <a class="navarrow" href=${prev ? "#/lesson/" + i : null} aria-disabled=${!prev} aria-label="Previous lesson">‹</a>
      <div class="lb-mid"><span class="lb-t">Lesson ${i + 1} of ${total} · <a href="#/">${goalsLabel(D, S.goal)}</a></span>
        <ol class="segs" aria-label="Lessons on this path">${steps.map((sid, k) => html`<li key=${sid}><a href=${"#/lesson/" + (k + 1)} title=${k + 1 + ". " + C[sid].n} aria-label=${"Lesson " + (k + 1) + ": " + C[sid].n}
          class=${"seg" + (k === i ? " seg-on" : S.done[sid] ? " seg-done" : "")} aria-current=${k === i ? "step" : null}></a></li>`)}</ol></div>
      <a class="navarrow" href=${next ? "#/lesson/" + (i + 2) : "#/done"} aria-label=${next ? "Next lesson" : "Finish"}>›</a>
    </div>
    ${planStrip(D, S, P)}
    <aside class=${"minimap" + (S.miniOff ? " minimap-off" : "")} aria-label="Map of your path">
      <div class="mm-head"><b>Map</b><span>${P.steps.filter((x) => S.done[x]).length}/${total} · lesson ${i + 1}</span>
        <button class="mm-tog" aria-expanded=${!S.miniOff} aria-label=${S.miniOff ? "Show the map" : "Hide the map"} onClick=${() => set({ miniOff: !S.miniOff })}>${S.miniOff ? "▢" : "–"}</button></div>
      ${S.miniOff ? null : html`<div class="cork mm-cork"><${CourseMap} D=${D} known=${P.known} goals=${S.goal} steps=${steps} current=${i} done=${S.done} compact pulse=${pulse} onPick=${go} /></div>
        <p class="mm-next">${next ? html`next: <a href=${"#/lesson/" + (i + 2)}>${trunc(next.n, 26)}</a>` : html`<a href="#/done">finish the path ★</a>`}</p>`}
    </aside>
    <div class="deck" key=${id + ":" + ci}>
      ${cur.k === "intro" ? html`<section class="board deck-card" data-medium="charcoal" data-theme="dark" aria-labelledby="lt">
          <div class="chalk"><span class="ch-kick">${kicker}</span>
          <h1 id="lt" class="ch-title">${c.n}</h1>
          <${M} as="p" cls="ch-sum" t=${c.s} />
          ${c.T ? null : html`<h2 class="ch-h">Key ideas</h2>${ideas}`}</div>
          <div class="intro-src" role="group" aria-label="From the Stanford course">
            <span class="src-k">From the Stanford course</span>
            ${lecK >= 0 ? html`<button class="src" onClick=${() => watchVid(lecK)}><b>▶ Lecture</b>${vids[lecK].by.replace("Stanford ", "")}: ${trunc(vids[lecK].title, 34)}</button>` : null}
            ${nbk ? html`<a class="src" href=${nbk.colab} target="_blank" rel="noopener" onClick=${() => seen("practice")}><b>Notebook ↗</b>${trunc(nbk.title, 34)}, in Colab</a>` : null}
            <a class="src" href=${ch ? ch.url : "https://porabook.com/book/"} target="_blank" rel="noopener"><b>Book ↗</b>${c.c == null ? "Principles of Robot Autonomy" : "Chapter " + c.c + ": " + trunc(ch.title, 30)}</a>
            ${lecK < 0 && vids.length ? html`<button class="src" onClick=${() => watchVid(0)}><b>▶ Video</b>${trunc(vids[0].title, 34)} · ${vids[0].by}</button>` : null}
          </div>
          <div class="intro-meta"><span>${cards.length} short cards · about ${pathMinutes(D, [id])} min</span>${c.T ? html`<${Listen} c=${c} onEnd=${() => seen("read")} />` : null}</div>
          ${c.T ? null : html`<p class="intro-note">The full written lesson is on its way. For now, these key ideas are the core; ${chapterLink} has the full treatment.</p>`}
        </section>`

      : cur.k === "read" ? html`<article class="card deck-card lessontext" aria-label=${cur.t}>
          <span class="kicker">${c.n} · ${readNo} of ${nreads} · written for BrainU</span>
          <div class="prose" dangerouslySetInnerHTML=${{ __html: tex(cur.h, true) }}></div></article>`

      : cur.k === "recap" ? html`<section class="board deck-card recap" data-medium="charcoal" data-theme="dark" aria-label="Recap">
          <div class="chalk"><span class="ch-kick">${c.n}</span><h2 class="ch-h">Recap</h2>${ideas}</div>
          <p class="intro-note">Written for this companion from Principles of Robot Autonomy${ch ? ", chapter " + c.c : ""}. ${chapterLink} has the full treatment.</p></section>`

      : cur.k === "watch" ? html`<section class="card deck-card watch" aria-labelledby="wt"><h2 id="wt">Watch</h2>
              <p class="src-line">${V.full ? html`<b>Official recording</b> from Stanford's ${V.by.replace("Stanford ", "")}, the course this book is written for.` : html`A short explainer by ${V.by}, not part of the Stanford course${lecK >= 0 ? html`; the <button class="linkish" onClick=${() => { setSel(lecK); setPlaying(false); }}>official lecture</button> is below` : ""}.`}</p>
              <figure class="video">
              <div class="screen">${playing && yt ? html`<iframe key=${yt} src=${`https://www.youtube-nocookie.com/embed/${yt}?autoplay=1&rel=0&modestbranding=1`} title=${V.title} allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen></iframe>`
                : html`<button class="play" onClick=${() => { setPlaying(true); seen("watch"); }} aria-label=${"Play " + V.title} style=${yt ? { backgroundImage: `url(https://i.ytimg.com/vi/${yt}/hqdefault.jpg)` } : null}><span>▶</span></button>`}</div>
              <figcaption>${V.title} · ${V.by} · ${V.len} <a href=${V.url || "https://youtu.be/" + yt} target="_blank" rel="noopener">YouTube ↗</a></figcaption>
              ${vids.length > 1 ? html`<div class="vpick" role="group" aria-label="Videos for this lesson">${vids.map((v, k) => html`<button key=${v.yt + k} aria-pressed=${k === vi} class=${k === vi ? "on" : ""} onClick=${() => { setSel(k); setPlaying(true); seen("watch"); }}>
                <span class="vp-k">${v.full ? "Official Stanford lecture" : (k === 0 ? "Short explainer" : "Also good") + " · " + v.len}</span><span class="vp-t">${v.title}</span><span class="vp-b">${v.by}</span></button>`)}</div>` : null}</figure></section>`

      : cur.k === "check" ? html`<section class="card deck-card quiz" aria-labelledby="qz">
          <h2 id="qz">Check yourself</h2>
          <${M} as="p" cls="qq" t=${qq} />
          <div role="radiogroup" aria-labelledby="qz" class="qopts">${choices.map((t, k) => {
            const cls = checked ? (k === correct ? " qopt-right" : k === picked ? " qopt-wrong" : "") : picked === k ? " qopt-on" : "";
            return html`<button key=${k} class=${"qopt" + cls} role="radio" aria-checked=${picked === k} disabled=${checked} onClick=${() => setPicked(k)}>
              <span class="qm">${checked && k === correct ? "✓" : checked && k === picked ? "✗" : "ABCD"[k]}</span><${M} t=${t} /></button>`; })}</div>
          ${checked ? html`<div class=${"feedback " + (ok ? "fb-ok" : "fb-no")} role="status"><b>${ok ? "Right." : "Not quite."}</b> <${M} t=${why} />${ok ? "" : html` <em>It's on your retry list for later.</em>`}</div>` : null}
          <div class="row">
            ${!checked ? html`<button class="am-button" disabled=${picked === null} onClick=${check}>Check answer</button>`
              : !ok ? html`<button class="linkish" onClick=${() => { setChecked(false); setPicked(null); }}>Try again</button>` : null}
          </div>
        </section>`

      : html`<section class="card deck-card practice" aria-labelledby="pr">
          <h2 id="pr">Practice</h2>
          <${M} as="p" t=${c.t} />
          <div class="row">
            ${nbk ? html`<a class="am-button am--secondary" href=${nbk.colab} target="_blank" rel="noopener" onClick=${() => seen("practice")}>Open the ${nbk.title} notebook in Colab ↗</a>` : null}
            <span class="intro-note">or read ${chapterLink}</span>
          </div>
          <div class="beyond"><span class="kicker">Beyond the course</span>
            ${(c.R || []).length ? html`<ul>${c.R.slice(0, 3).map((r) => html`<li key=${r.u}>${r.v ? html`<button class="mini-play" aria-label=${"Watch the 30-second explainer for " + r.t} onClick=${() => setVideo({ t: r.t, src: r.v, u: r.u })}>▶</button>` : null}<a href=${r.u} target="_blank" rel="noopener">${r.t}</a>${r.y ? html` <small>${r.y}</small>` : null}</li>`)}</ul>` : null}
            <a class="linkish" href=${arxivSearch(c.n)} target="_blank" rel="noopener">Newest work on ${c.n} on arXiv ↗</a></div>
        </section>`}

      <nav class="deck-foot" aria-label="Cards in this lesson">
        <button class="linkish deck-back" disabled=${ci === 0} onClick=${back}>‹ Back</button>
        <ol class="deck-dots">${cards.map((x, k) => html`<li key=${k}><button aria-label=${k + 1 + ". " + x.t} title=${x.t} aria-current=${k === ci ? "step" : null}
          class=${k === ci ? "on" : k < ci ? "past" : ""} onClick=${() => setCard(k)}></button></li>`)}</ol>
        <button class="am-button deck-next" onClick=${fwd}>${last ? (next ? "Next lesson →" : "Finish the path ★") : cur.k === "check" && !checked ? "Skip →" : cards[ci + 1].k === "read" ? "Next →" : "Next: " + cards[ci + 1].t.toLowerCase() + " →"}</button>
      </nav>
    </div>
    ${video ? html`<${VideoModal} v=${video} onClose=${() => setVideo(null)} />` : null}
  </main>`;
}

// ── Brain University's research graph: loaded only when a page needs it ──
const loaded = {};
const loadScript = (src) => loaded[src] || (loaded[src] = new Promise((ok, no) => {
  const t = document.createElement("script"); t.src = src; t.onload = ok; t.onerror = () => no(new Error(src)); document.head.appendChild(t);
}));
let researchP = null;
const loadResearch = () => researchP || (researchP = (async () => {
  for (const src of ["data.js", "courses/pora_bu.js", "open_problems.js", "videos/manifest.js"]) await loadScript(src);
  return { B: window.BU_DATA, OP: (window.OPEN_PROBLEMS || {}).problems || [], V: window.ARXIVIS_VIDEOS || {} };
})());
let graphLibP = null;
const loadGraphLib = () => graphLibP || (graphLibP = loadScript("vendor/three.min.js").then(() => loadScript("vendor/3d-force-graph.min.js")));
function useResearch() {
  const [R, setR] = useState(null), [err, setErr] = useState(false);
  useEffect(() => { loadResearch().then(setR, () => setErr(true)); }, []);
  return [R, err];
}
const vidFor = (V, id) => V[id] || null;
const norm = (x) => String(x).toLowerCase().replace(/[_\-]+/g, " ").replace(/\s+/g, " ").trim();

// The real 3D graph (3d-force-graph on three.js): every Brain University topic, with the
// course as its own cluster and your path glowing gold along a lit route.
function Graph3D({ B, path = [], current = null, mode = "all", height = 520, onPick }) {
  const el = useRef(), fg = useRef(), [fail, setFail] = useState(false);
  const pathSet = new Set(path), pora = B.PORA || {};
  useEffect(() => {
    let alive = true;
    loadGraphLib().then(() => {
      if (!alive || !el.current) return;
      if (!window.ForceGraph3D) { setFail(true); return; }
      const keep = (n) => mode === "all" || (mode === "pora" ? n.cluster === pora.clusterId || n.cluster === pora.backgroundClusterId || pathSet.has(n.id) : pathSet.has(n.id) || B.EDGES.some(([a, b]) => (a === n.id && pathSet.has(b)) || (b === n.id && pathSet.has(a))));
      const nodes = B.NODES.filter(keep).map((n) => ({ ...n })), ids = new Set(nodes.map((n) => n.id));
      const links = B.EDGES.filter(([a, b]) => ids.has(a) && ids.has(b)).map(([a, b]) => ({ source: a, target: b }));
      path.slice(1).forEach((id, k) => { if (ids.has(id) && ids.has(path[k])) links.push({ source: path[k], target: id, route: true }); });
      const color = {}; B.CLUSTERS.forEach((c) => (color[c.id] = c.color));
      const cname = {}; B.CLUSTERS.forEach((c) => (cname[c.id] = c.name));
      try {
        const G = window.ForceGraph3D({ controlType: "orbit", rendererConfig: { alpha: true, antialias: true } })(el.current)
          .width(el.current.clientWidth).height(height).backgroundColor("rgba(0,0,0,0)")
          .graphData({ nodes, links })
          .nodeLabel((n) => `<div class="g3tip"><b>${n.name}</b><br>${cname[n.cluster] || ""}${pathSet.has(n.id) ? "<br>★ on your path" : ""}</div>`)
          .nodeColor((n) => (n.id === current ? "#c4221c" : pathSet.has(n.id) ? "#e0a100" : color[n.cluster] || "#8a7f6a"))
          .nodeVal((n) => (pathSet.has(n.id) ? 9 : 1.5 + Math.min(6, (n.degree || 1) / 3)))
          .nodeOpacity(0.95)
          .linkColor((l) => (l.route ? "#c4221c" : "rgba(70,55,35,0.28)"))
          .linkWidth((l) => (l.route ? 2.2 : 0.4))
          .linkDirectionalParticles((l) => (l.route ? 3 : 0)).linkDirectionalParticleWidth(2.6).linkDirectionalParticleColor(() => "#e0a100")
          .onNodeClick((n) => onPick && onPick(n));
        G.nodeRelSize(5);
        // weaker repulsion keeps small, separate topics from drifting off and shrinking the view
        const ch = G.d3Force("charge"); if (ch && ch.strength) ch.strength(-14);
        const fit = () => fg.current === G && G.zoomToFit(800, 30, mode === "pora" && path.length ? (n) => pathSet.has(n.id) || n.cluster === pora.clusterId : undefined);
        G.cooldownTicks(120).onEngineStop(fit); setTimeout(fit, 1600);
        fg.current = G;
        const on = () => el.current && G.width(el.current.clientWidth);
        addEventListener("resize", on); fg.current.__off = () => removeEventListener("resize", on);
      } catch (e) { setFail(true); }
    }, () => setFail(true));
    return () => { alive = false; if (fg.current) { fg.current.__off && fg.current.__off(); fg.current._destructor && fg.current._destructor(); fg.current = null; } if (el.current) el.current.innerHTML = ""; };
  }, [B, mode, path.join(), current, height]);
  return fail ? html`<div class="g3d-fail" style=${{ height: height + "px" }}>The 3D graph needs WebGL, which this browser has turned off.</div>`
    : html`<div class="g3d" ref=${el} style=${{ height: height + "px" }} aria-label="3D knowledge graph. Drag to orbit, scroll to zoom, hover a node for its name."></div>`;
}

function VideoModal({ v, onClose }) {
  useEffect(() => { const k = (e) => e.key === "Escape" && onClose(); addEventListener("keydown", k); return () => removeEventListener("keydown", k); }, []);
  return html`<div class="vmodal-scrim" onClick=${onClose}></div>
    <div class="vmodal" role="dialog" aria-modal="true" aria-label=${v.t}>
      <video src=${v.src} controls autoplay playsinline></video>
      <div class="row"><b>${v.t}</b><span style=${{ flex: 1 }}></span>${v.u ? html`<a class="linkish" href=${v.u} target="_blank" rel="noopener">Read on arXiv ↗</a>` : null}<button class="am-button am--secondary" onClick=${onClose}>Close</button></div></div>`;
}
const ExplainerCard = ({ p, onPlay }) => html`<button class="xcard" onClick=${() => onPlay(p)}>
  <span class="xplay" aria-hidden="true">▶</span><span class="xmeta"><span class="xk">30-second explainer${p.y ? " · " + p.y : ""}</span><span class="xt">${p.t}</span>${p.from ? html`<span class="xf">near ${p.from}</span>` : null}</span></button>`;

// Missing bridges and quiet clusters from Brain University's research graph.
function Gaps({ OP, V, only, onPlay, limit }) {
  const [kind, setKind] = useState("missing_bridge");
  const list = (only || OP).filter((p) => !only ? p.kind === kind : true).slice(0, limit || 999);
  const count = (k) => OP.filter((p) => p.kind === k).length;
  return html`<div class="gaps">
    ${only ? null : html`<div class="tabs2" role="tablist"><button role="tab" aria-selected=${kind === "missing_bridge"} class=${kind === "missing_bridge" ? "on" : ""} onClick=${() => setKind("missing_bridge")}>Missing bridges · ${count("missing_bridge")}</button>
      <button role="tab" aria-selected=${kind === "stale_cluster"} class=${kind === "stale_cluster" ? "on" : ""} onClick=${() => setKind("stale_cluster")}>Quiet clusters · ${count("stale_cluster")}</button></div>`}
    <div class="gapgrid">${list.map((g) => html`<article key=${g.title} class="card gap">
      <span class=${"gk " + (g.kind === "missing_bridge" ? "gk-b" : "gk-q")}>${g.kind === "missing_bridge" ? "Missing bridge" : "Quiet cluster"} · score ${Math.round(g.score)}</span>
      <h3>${g.title}</h3><p>${g.why}</p>
      <div class="chips">${g.concepts.map((c) => html`<span key=${c} class="cchip">${norm(c)}</span>`)}</div>
      ${(g.closest_papers || []).length ? html`<div class="closest"><span class="xk">Closest papers</span>${g.closest_papers.slice(0, 3).map((cp) => {
        const src = vidFor(V, cp.id), u = cp.id.startsWith("arx:") ? "https://arxiv.org/abs/" + cp.id.slice(4) : null;
        return html`<div key=${cp.id} class="cp">${src ? html`<button class="mini-play" aria-label=${"Watch the explainer for " + cp.title} onClick=${() => onPlay({ t: cp.title, src, u })}>▶</button>` : html`<span class="mini-play off">·</span>`}<span>${cp.title}</span></div>`; })}</div>` : null}
    </article>`)}</div></div>`;
}

function GraphPage({ D, S, P }) {
  const [R, err] = useResearch(), [mode, setMode] = useState(P ? "pora" : "all"), [pick, setPick] = useState(null), [video, setVideo] = useState(null);
  if (err) return html`<p class="loading">Brain University's graph data didn't load.</p>`;
  if (!R) return html`<p class="loading">Loading the knowledge graph…</p>`;
  const W = {}; Object.entries(D.C).forEach(([id, c]) => (W[c.w] = id));
  const path = P ? P.steps.map((id) => D.C[id].w) : [], i = P ? Math.min(S.i, P.steps.length - 1) : -1;
  const cl = {}; R.B.CLUSTERS.forEach((c) => (cl[c.id] = c));
  const papers = [...new Map((P ? P.steps : Object.keys(D.C)).flatMap((id) => (D.C[id].R || []).map((r) => ({ ...r, src: r.v, from: D.C[id].n }))).map((r) => [r.u, r])).values()];
  const pc = pick && W[pick.id] ? D.C[W[pick.id]] : null, pk = pc && P ? P.steps.indexOf(W[pick.id]) : -1;
  return html`<main class="graphpage">
    <header class="gp-head"><div><span class="kicker">Brain University</span><h1>The knowledge graph</h1>
      <p>Principles of Robot Autonomy inside Brain University's research graph: ${R.B.NODES.length} concepts across ${R.B.CLUSTERS.length} topics.${P ? " Your path is gold, strung in red." : ""} Drag to orbit, scroll to zoom, click a concept.</p></div>
      <div class="seg3" role="group" aria-label="What to show">${[["all", "Everything"], ["pora", "Robot autonomy"], ...(P ? [["path", "My path"]] : [])].map(([k, t]) => html`<button key=${k} aria-pressed=${mode === k} class=${mode === k ? "on" : ""} onClick=${() => setMode(k)}>${t}</button>`)}</div></header>
    <div class="g3d-wrap">
      <${Graph3D} B=${R.B} path=${path} current=${i >= 0 ? path[i] : null} mode=${mode} height=${560} onPick=${setPick} />
      ${pick ? html`<aside class="g3d-card"><span class="kicker" style=${{ color: (cl[pick.cluster] || {}).color }}>${(cl[pick.cluster] || {}).name}</span><b>${pick.name}</b>
        ${pc ? html`<p>${pc.s}</p>${pk >= 0 ? html`<a class="am-button" href=${"#/lesson/" + (pk + 1)}>Open lesson ${pk + 1}</a>` : html`<span class="hint">Part of the course, not on your current path.</span>`}` : html`<p>${(cl[pick.cluster] || {}).blurb || ""}</p><a class="linkish" href="Brain%20University.html">Explore it in the full Brain University app →</a>`}
        <button class="linkish" onClick=${() => setPick(null)}>Close</button></aside>` : null}
      <div class="clegend">${R.B.CLUSTERS.map((c) => html`<span key=${c.id}><i style=${{ background: c.color }}></i>${c.name}</span>`)}</div>
    </div>
    <section class="gp-sec"><h2>Gaps the graph found</h2><p class="hint">From arXivis: pairs of busy topics no paper has connected yet, and clusters that have gone quiet. Each is open territory for new work.</p>
      <${Gaps} OP=${R.OP} V=${R.V} onPlay=${setVideo} /></section>
    <section class="gp-sec"><h2>30-second explainers</h2><p class="hint">Animated explainers for recent papers ${P ? "near the lessons on your path" : "near the course"}.</p>
      <div class="xgrid">${papers.map((p) => html`<${ExplainerCard} key=${p.u} p=${p} onPlay=${setVideo} />`)}</div></section>
    ${video ? html`<${VideoModal} v=${video} onClose=${() => setVideo(null)} />` : null}
  </main>`;
}

function Done({ D, S, P }) {
  useEffect(() => trackEvent("path-finished"), []);
  const [R] = useResearch(), [video, setVideo] = useState(null);
  const n = P.steps.length, learned = P.steps.filter((id) => S.done[id]).length;
  const retry = Object.keys(S.wrong || {}).filter((w) => P.steps.includes(w)).length;
  const papers = [...new Map(P.steps.flatMap((id) => (D.C[id].R || []).map((r) => ({ ...r, src: r.v, from: D.C[id].n }))).map((r) => [r.u, r])).values()].slice(0, 6);
  const names = new Set(P.steps.flatMap((id) => [norm(D.C[id].n), norm(D.C[id].w)]));
  const near = R ? R.OP.filter((g) => g.concepts.some((c) => names.has(norm(c)) || [...names].some((x) => x.length > 5 && (norm(c).includes(x) || x.includes(norm(c)))))) : [];
  const gaps = R ? (near.length ? near : [...R.OP].sort((a, b) => b.score - a.score)).slice(0, 3) : [];
  return html`<main class="done">
    <section class="done-hero">
      <div class="card done-card">
        <span class="kicker">Path complete ★</span>
        <h1>${goalsLabel(D, S.goal)}</h1>
        <div class="stats">
          <div><b>${n}</b><span>lessons</span></div><div><b>${learned}/${n}</b><span>checks passed</span></div>
          <div><b>${retry}</b><span>to retry</span></div></div>
        <p>You can now work through ${goalsLabel(D, S.goal).toLowerCase()} with the course's own lectures and notebooks behind you. Next: see where it sits in the bigger graph, and where the open questions are.</p>
        <div class="row"><a class="am-button" href="#/graph">Explore the knowledge graph →</a><a class="linkish" href="#/start">Pick new goals</a>
          ${retry ? html`<a class="linkish" href=${"#/lesson/" + (P.steps.indexOf(Object.keys(S.wrong).find((w) => P.steps.includes(w))) + 1)}>Retry the ${retry} you missed</a>` : null}</div>
      </div>
      <div class="cork cork-sm"><${CourseMap} D=${D} known=${P.known} goals=${S.goal} steps=${P.steps} current=${-1} done=${Object.fromEntries(P.steps.map((id) => [id, true]))} /></div>
    </section>
    <section class="gp-sec"><h2>Your path inside the knowledge graph</h2>
      <p class="hint">Your ${n} lessons are gold, strung in red. Everything they connect to in Brain University sits around them. Drag to orbit.</p>
      ${R ? html`<${Graph3D} B=${R.B} path=${P.steps.map((id) => D.C[id].w)} mode="path" height=${420} />` : html`<p class="loading">Loading the graph…</p>`}
      <a class="linkish" href="#/graph">Open the full graph →</a></section>
    ${papers.length ? html`<section class="gp-sec"><h2>Watch what's next</h2><p class="hint">30-second explainers of recent papers built on what you just learned.</p>
      <div class="xgrid">${papers.map((p) => html`<${ExplainerCard} key=${p.u} p=${p} onPlay=${setVideo} />`)}</div></section>` : null}
    ${gaps.length ? html`<section class="gp-sec"><h2>${near.length ? "Open problems near your path" : "Open problems in the research graph"}</h2>
      <p class="hint">${near.length ? "Gaps arXivis found that touch the concepts you just learned." : "None touch your path directly yet; these are the strongest gaps overall."}</p>
      ${R ? html`<${Gaps} OP=${R.OP} V=${R.V} only=${gaps} onPlay=${setVideo} />` : null}<a class="linkish" href="#/graph">See all the gaps →</a></section>` : null}
    ${video ? html`<${VideoModal} v=${video} onClose=${() => setVideo(null)} />` : null}
  </main>`;
}

function Explore({ hasPath }) {
  const items = [...(hasPath ? [["Your path on the course map", "Every chapter on cork, with your lessons pinned in order and a red string through them.", "#/path"]] : []),
    ["The knowledge graph", "The course inside Brain University's graph in 3D, with research gaps and paper explainers.", "#/graph"],
    ["The full Brain University app", "Tours, podcasts, the arXivis feed and everything else.", "Brain%20University.html"],
    ["The course atlas", "Every PoRA concept and how they connect, on one page.", "courses/pora-atlas.html"],
    ["Principles of Robot Autonomy", "The book, lectures and exercises, free from Stanford.", "https://porabook.com"],
    ["The classroom prototype", "The earlier chalkboard-and-desk version of this companion.", "classroom.html"]];
  return html`<main class="explore"><h1>Explore</h1>
    <div class="egrid">${items.map(([t, d, u]) => html`<a key=${t} class="card ecard" href=${u} target=${u.startsWith("http") ? "_blank" : null} rel="noopener"><h2>${t}</h2><p>${d}</p></a>`)}</div></main>`;
}

// ── app ─────────────────────────────────────────────────────────────
function load() {
  const S = { bg: null, goal: null, started: false, i: 0, done: {}, passed: 0, wrong: {}, tick: 0, justBuilt: 0,
    placed: null, seen: {}, rev: {}, last: 0, days: [], weekGoal: 3, mins: 20, plan: null };
  try { const s = JSON.parse(localStorage.getItem(KEY) || "null"); if (s) SAVED.forEach((k) => { if (k in s) S[k] = s[k]; }); } catch (e) {}
  if (typeof S.goal === "string") S.goal = [S.goal];
  if (S.goal && !S.goal.length) S.goal = null;
  S.prevLast = S.last; // when you were last here, for the welcome-back warm-up
  return S;
}

function App() {
  const [D, setD] = useState(null), [err, setErr] = useState(false), [S, setS] = useState(load), [route, setRoute] = useState(parse());
  useEffect(() => {
    fetch("prototype/course.json").then((r) => { if (!r.ok) throw new Error(r.status); return r.json(); }).then(setD).catch(() => setErr(true));
    const on = () => setRoute(parse()); addEventListener("hashchange", on); return () => removeEventListener("hashchange", on);
  }, []);
  const set = (patch) => setS((s) => { const d = today(), n = { ...s, ...patch, last: now(), days: (s.days || []).includes(d) ? s.days : [...(s.days || []).slice(-90), d] }; try { const o = {}; SAVED.forEach((k) => (o[k] = n[k])); localStorage.setItem(KEY, JSON.stringify(o)); } catch (e) {} return n; });
  // Start over: forget the path and all progress in this browser and go back to the front door.
  // #/reset does it without asking, for testing from scratch.
  const reset = (ask) => {
    if (ask && !window.confirm("Start over? This clears your path and progress in this browser.")) return;
    try { localStorage.removeItem(KEY); } catch (e) {}
    setS(load()); trackEvent("start-over"); nav("#/home");
  };
  useEffect(() => { if (route.page === "reset") reset(false); }, [route.page]);
  useEffect(() => { window.scrollTo(0, 0); }, [route.page]);
  // one page view per screen; lessons by number, not by part, so #/lesson/3/check counts as lesson 3
  useEffect(() => { track("/" + (route.page || "") + (route.page === "lesson" && route.arg ? "/" + route.arg : ""), document.title); }, [route.page, route.arg]);
  if (err) return html`<p class="loading">The course didn't load. Run a local server in the design folder (python3 -m http.server 8000) and reload.</p>`;
  if (!D) return html`<p class="loading">Loading the course…</p>`;
  const goals = (S.goal || []).filter((g) => D.C[g]), hasPath = !!(S.bg && goals.length);
  const P = hasPath ? pathFor(D, S.bg, goals, S.placed) : null, s = { ...S, goal: goals };
  let page = route.page, body;
  const at = P ? Math.min(S.i, P.steps.length - 1) : 0;
  const next = P && P.steps.some((id) => !S.done[id]) ? { href: "#/lesson/" + (at + 1), label: S.started ? "Continue lesson " + (at + 1) : "Start lesson 1" } : null;
  if (page === "explore") body = html`<${Explore} hasPath=${hasPath} />`;
  else if (page === "graph") body = html`<${GraphPage} D=${D} S=${s} P=${P} />`;
  else if (page === "start") body = html`<${Start} D=${D} S=${s} set=${set} />`;
  else if (page === "home" || page === "reset" || !hasPath) { page = "home"; body = html`<${Welcome} D=${D} set=${set} next=${hasPath ? next : null} onReset=${() => reset(true)} />`; }
  else if (page === "path") body = html`<${PathPage} D=${D} S=${s} P=${P} set=${set} />`;
  else if (page === "lesson") body = html`<${Lesson} D=${D} S=${s} P=${P} set=${set} n=${route.arg ? parseInt(route.arg, 10) - 1 || 0 : Math.min(S.i, P.steps.length - 1)} part=${route.part} />`;
  else if (page === "done") body = html`<${Done} D=${D} S=${s} P=${P} />`;
  else body = html`<${Home} D=${D} S=${s} P=${P} set=${set} onReset=${() => reset(true)} />`;
  // the hub and the front door have their own button for the next step, so the nav doesn't repeat it
  return html`<${TopNav} page=${page} hasPath=${hasPath} next=${page === "" || page === "home" ? null : next} />${body}`;
}

render(html`<${App} />`, document.getElementById("app"));
